document.addEventListener("DOMContentLoaded", function () {

    let form = document.getElementById("formContato");
    let lista = document.getElementById("listaContatos");
    let mensagem = document.getElementById("mensagem");
    let btnTema = document.getElementById("btnTema");
    let msgAjax = document.getElementById("mensagemAjax");

    // AJAX
    fetch("dados.json")
        .then(response => response.json())
        .then(dados => {
            msgAjax.textContent = dados.mensagem;
        });

    // Tema
    btnTema.addEventListener("click", function () {
        document.body.classList.toggle("tema-escuro");
    });

    // Formulário
    form.addEventListener("submit", function (event) {
        event.preventDefault();

        let nome = document.getElementById("nome").value;
        let email = document.getElementById("email").value;
        let telefone = document.getElementById("telefone").value;

        if (nome === "" || email === "" || telefone === "") {
            mensagem.textContent = "Preencha tudo!";
            mensagem.style.color = "red";
            return;
        }

        let item = document.createElement("li");
        item.className = "list-group-item";
        item.textContent = nome + " - " + email + " - " + telefone;

        lista.appendChild(item);

        mensagem.textContent = "Cadastrado!";
        mensagem.style.color = "green";

        form.reset();
    });

});